function at(k){return tx(AL[k])}
function opt(v,label,cur){return '<option value="'+esc(v)+'"'+(String(cur)===String(v)?' selected':'')+'>'+esc(label)+'</option>'}
function getPath(o,p){return p.split('.').reduce(function(a,k){return a==null?undefined:a[k]},o)}
function setPath(o,p,v){var ks=p.split('.'),x=o;for(var i=0;i<ks.length-1;i++){var k=ks[i];if(x[k]==null)x[k]=/^\d+$/.test(ks[i+1])?[]:{};x=x[k]}x[ks[ks.length-1]]=v}
function unitOpts(){return UNIT_LIST.map(function(u){return [u.id,tx(u.names)+' ('+u.id+')']})}
function itemOpts(){return ITEMS.slice().sort(function(a,b){return a.cat<b.cat?-1:a.cat>b.cat?1:RAR[a.rar].order-RAR[b.rar].order}).map(function(i){return [i.id,tx(i.names)+' · '+tx(RAR[i.rar].names)]})}

