/* ---------- db writes ---------- */
function retry(fn){return fn().catch(function(e){var c=errCode(e);if(c==='unavailable'||c==='resource_exhausted')return new Promise(function(r){setTimeout(r,800+Math.random()*700)}).then(fn);throw e})}
function dbSet(col,id,body){return retry(function(){return CL.db.collection(col).doc(id).set(body)})}
function dbDel(col,id){return retry(function(){return CL.db.collection(col).doc(id).delete()})}
function runOps(ops,label){var i=0,done=0,fail=0,n=ops.length;UI.modal={kind:'admbusy',busy:true,label:label,done:0,total:n};render();
  return new Promise(function(resolve){function next(){if(i>=n){if(done+fail>=n)finish();return}var op=ops[i++];opTimed(op).then(function(){done++},function(){fail++}).then(function(){
    UI.modal&&UI.modal.kind==='admbusy'&&(UI.modal.done=done+fail);var p=document.getElementById('admprog');if(p)p.textContent=(done+fail)+' / '+n;next()})}
    var ended=false;function finish(){if(ended)return;ended=true;UI.modal=null;render();if(fail&&OPS_SLOW){OPS_SLOW=false;UI.modal={kind:'admslow'};render()}else toast(fail?at('writefail')+' ('+fail+')':at('done')+' · '+done);resolve(fail)}
    if(!n)finish();for(var k=0;k<Math.min(slOn()?60:4,n);k++)next()})}
/* a database write that never answers (lost connection, or the free daily quota used up) counts as failed after 25 s, so the screen never hangs */
function opTimed(op){return new Promise(function(res,rej){var tm=setTimeout(function(){OPS_SLOW=true;rej({code:'timeout'})},25000);op().then(function(v){clearTimeout(tm);res(v)},function(e){clearTimeout(tm);rej(e)})})}
var OPS_SLOW=false;
function writeErr(e){toast(errCode(e)==='invalid_argument'?at('noperm'):at('writefail'))}
/* defaults shipped with a game update that the database does not have yet (never touches what is there) */
function missingDefaults(){var r={};COLS.forEach(function(c){if(!CL.seeded[c])return;var have={};(CONTENT[c]||[]).forEach(function(d){have[d.id]=1});var ms=DEFAULTS[c].filter(function(d){return !have[d.id]});if(ms.length)r[c]=ms});return r}
function restBanners(){if(!CL.seeded.banners)return [];return DEFAULTS.banners.filter(function(d){if(!d.off)return false;var c=(CONTENT.banners||[]).filter(function(x){return x.id===d.id})[0];return c&&!c.off})}
/* brand-new items join their group summon banner (pools are stored in the DB, so they would otherwise never appear) */
function growBanners(){if(!CL.seeded.banners||!CL.seeded.items)return [];var have={};(CONTENT.items||[]).forEach(function(d){have[d.id]=1});
  return DEFAULTS.banners.filter(function(d){return BANNER_GROUPS[d.id]}).map(function(d){var c=(CONTENT.banners||[]).filter(function(x){return x.id===d.id})[0];if(!c)return null;var cur=c.pool||[];
    var add=d.pool.filter(function(id){return cur.indexOf(id)<0&&(!have[id]||/^fr\d\d$/.test(id))});
    /* frames now have their own banner: take them back out of any other group banner (e.g. after an earlier update) */
    var drop=cur.filter(function(id){if(d.pool.indexOf(id)>=0)return false;if(/^fr\d\d$/.test(id))return true;var it=ITEM[id];if(!it)return false;
      /* moved to another group box (auras / wings split), common fashion that is now shop-only, or no longer fits the box (old pets) */if(BANNER_GROUPS[d.id]&&!BANNER_GROUPS[d.id](it))return true;return it.rar==='common'&&d.id!=='bxF'&&d.id!=='bxS'||DEFAULTS.banners.some(function(o){return o.id!==d.id&&BANNER_GROUPS[o.id]&&o.pool.indexOf(id)>=0})});
    return add.length||drop.length?{d:d,c:c,add:add,drop:drop}:null}).filter(Boolean)}
function addMissing(){var miss=missingDefaults(),ops=[],gb=growBanners();restBanners().forEach(function(d){var c=CONTENT.banners.filter(function(x){return x.id===d.id})[0];ops.push(function(){return dbSet('banners',d.id,Object.assign({},c,{off:true}))})});COLS.forEach(function(c){(miss[c]||[]).forEach(function(d){ops.push(function(){return dbSet(c,d.id,d)})})});
  /* banner pools last, so every pooled item already exists */gb.forEach(function(g){ops.push(function(){return dbSet('banners',g.d.id,Object.assign({},g.c,{pool:(g.c.pool||[]).filter(function(id){return g.drop.indexOf(id)<0}).concat(g.add),names:g.d.names,sub:g.d.sub}))})});if(ops.length)return runOps(ops,at('newcb'))}
function seedCols(cols){var ops=[];cols.forEach(function(col){if(col==='config'){ops.push(function(){return retry(function(){return CL.db.doc('settings/config').set(DEFAULTS.config)})});return}
  DEFAULTS[col].forEach(function(d){ops.push(function(){return dbSet(col,d.id,d)})})});return runOps(ops,at('seed'))}
function replaceAll(content){var cols=COLS.filter(function(c){return Array.isArray(content[c])});
  Promise.all(cols.map(function(col){return CL.db.collection(col).get().then(function(s){return s.docs.map(function(d){return d.id})},function(){return []})})).then(function(existing){
    var ops=[];cols.forEach(function(col,ci){var keep={};content[col].forEach(function(d){keep[d.id]=1;ops.push(function(){return dbSet(col,d.id,d)})});
      existing[ci].forEach(function(id){if(!keep[id])ops.push(function(){return dbDel(col,id)})})});
    if(isO(content.config))ops.push(function(){return retry(function(){return CL.db.doc('settings/config').set(cleanConfig(content.config))})});
    var hc={};cols.forEach(function(col,ci){if(HIST_COLS.indexOf(col)<0)return;var newIds={};content[col].forEach(function(d){newIds[d.id]=1;var o=curDoc(col,d.id);if(canon(o)!==canon(d))(hc[col]=hc[col]||[]).push({id:d.id,v:d,old:o})});
      existing[ci].forEach(function(id){if(!newIds[id])(hc[col]=hc[col]||[]).push({id:id,v:null,old:curDoc(col,id)})})});
    if(isO(content.config))hc.config=[{id:'config',v:cleanConfig(content.config),old:JSON.parse(JSON.stringify(CFG))}];
    runOps(ops,at('writing')).then(function(){Object.keys(hc).forEach(function(c){histAppend(c,hc[c])})})})}

