document.addEventListener('input',function(e){var el=e.target;if(el&&/^give_(coin|gems|tickets|lvl)$/.test(el.id||'')&&UI.modal&&UI.modal.kind==='admpgive')giKeep(UI.modal)});

Object.assign(AL,{pw_btn:m('ลืมรหัส','Forgot PW','忘记密码'),pw_title:m('นักเรียนลืมรหัสผ่าน','Student forgot password','学生忘记密码'),pw_copy:m('คัดลอก','Copy','复制'),pw_mail:m('อีเมลในระบบ','Sign-in e-mail','登录邮箱'),
 pw_why:m('ครูดูรหัสเดิมไม่ได้ เพราะระบบเก็บรหัสแบบเข้ารหัสทางเดียว (ไม่มีใครเห็นได้ รวมถึงครู) เพื่อความปลอดภัยของนักเรียน · วิธีที่ใช้คือให้นักเรียนตั้งรหัสใหม่ด้วย ID เดิม ข้อมูลเกมอยู่ครบทุกอย่าง','Passwords cannot be shown — they are stored one-way encrypted, so nobody (teacher included) can read them. Instead the student sets a new password with the same ID; all game data stays.','密码无法查看——系统单向加密存储,任何人(包括老师)都看不到。改为让学生用原ID设置新密码,游戏数据全部保留。'),
 pw_s1:m('ยืนยันกับนักเรียนว่าเป็นเจ้าของบัญชีนี้จริง','Confirm the student really owns this account','确认学生确实是该账号主人'),
 pw_s2:m('ลบบัญชีเข้าสู่ระบบเดิมใน Firebase Console','Delete the old sign-in in the Firebase Console','在 Firebase 控制台删除旧登录账号'),
 pw_s2h:m('เปิดลิงก์ด้านล่าง › แท็บ Users › วางอีเมลในช่องค้นหา › กด ⋮ ท้ายแถว › Delete account (ลบเฉพาะบัญชีเข้าสู่ระบบ ข้อมูลเกมไม่หาย)','Open the link › Users tab › paste the e-mail into search › ⋮ at the end of the row › Delete account (only the sign-in is removed; game data stays)','打开链接 › Users › 搜索该邮箱 › 行末 ⋮ › Delete account(只删登录,游戏数据保留)'),
 pw_open:m('เปิด Firebase Console › Authentication','Open Firebase Console › Authentication','打开 Firebase 控制台 › Authentication'),
 pw_s3:m('กดปุ่มนี้เพื่อปลดล็อกข้อมูลเกมให้บัญชีใหม่','Press this to let the new sign-in use the save','点此让新账号接管存档'),
 pw_s4:m('ส่งข้อความนี้ให้นักเรียน','Send this to the student','把这段话发给学生'),
 pw_msg:m('ครูรีเซ็ตให้แล้ว ให้กด “สมัครสมาชิก” แล้วใช้ ID เดิม: {id} ตั้งรหัสผ่านใหม่ (อย่างน้อย 8 ตัว มีทั้งตัวอักษรและตัวเลข) ตัวละครและของทุกอย่างยังอยู่ครบ · จดรหัสใหม่เก็บไว้ด้วยนะ','Your teacher reset it: tap “Sign up”, use your same ID: {id}, and choose a new password (8+ characters with letters and numbers). Your character and items are all still there. Write the new password down!','老师已重置:点“注册”,用原来的ID:{id},设置新密码(至少8位,含字母和数字)。角色和物品都还在。记得记下新密码!'),
 pw_note:m('ถ้าข้ามขั้นที่ 2 นักเรียนจะสมัครไม่ได้ (ระบบแจ้งว่า ID ถูกใช้แล้ว) · ถ้าข้ามขั้นที่ 3 บัญชีใหม่จะเข้าข้อมูลเดิมไม่ได้ เพื่อกันคนอื่นแอบอ้าง','Skip step 2 and sign-up fails (ID taken) · skip step 3 and the new sign-in cannot open the old save (stops impersonation)','跳过第2步则注册失败(ID已占用)· 跳过第3步则新账号无法打开旧存档(防冒用)')});
Object.assign(AL,{gl_t:m('เพิ่มเลเวล','Add levels','增加等级'),gl_h:m('ใส่ 0–100 · เลเวลขึ้นทันทีเมื่อนักเรียนเปิดเกม (ไม่แจกเพชร/ตั๋วของการเลเวลอัป) · ระบบตรวจรู้ว่าเป็นของครู ไม่ถือว่าโกง','0–100 · applied when the student opens the game (no level-up gems/tickets) · the checker knows it came from you','0–100 · 学生打开游戏时生效(不发升级奖励)· 核验系统知道是老师给的')});
Object.assign(AL,{tg_t:m('ส่งฉายา','Give a title','赠送称号'),tg_none:m('— ไม่ส่งฉายา —','— no title —','— 不赠送 —'),tg_has:m('ฉายาที่ครูส่งให้แล้ว','Titles you gave','已赠送的称号'),tg_rev:m('ถอนฉายานี้','Take this title back','收回此称号')});
